#!/usr/bin/env bun
import { render } from "./engine.ts";
import { readFileSync } from "node:fs";

function main(): void {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    process.stderr.write("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json\n");
    process.exit(1);
  }
  const [templatePath, dataPath] = args;

  let template: string;
  let dataText: string;
  try {
    template = readFileSync(templatePath, "utf-8");
  } catch (e) {
    process.stderr.write(`Error reading template file: ${(e as Error).message}\n`);
    process.exit(1);
  }
  try {
    dataText = readFileSync(dataPath, "utf-8");
  } catch (e) {
    process.stderr.write(`Error reading data file: ${(e as Error).message}\n`);
    process.exit(1);
  }

  let data: unknown;
  try {
    data = JSON.parse(dataText);
  } catch (e) {
    process.stderr.write(`Error parsing JSON: ${(e as Error).message}\n`);
    process.exit(1);
  }

  let output: string;
  try {
    output = render(template, data);
  } catch (e) {
    process.stderr.write(`Render error: ${(e as Error).message}\n`);
    process.exit(1);
  }

  process.stdout.write(output);
}

main();

