// src/engine.ts

interface Position {
  line: number;
  col: number;
}

type Node =
  | { type: 'text'; value: string }
  | { type: 'interp'; path: string; pos: Position }
  | { type: 'raw'; path: string; pos: Position }
  | { type: 'if'; condition: string; body: Node[]; elseBody: Node[]; pos: Position }
  | { type: 'each'; collection: string; body: Node[]; elseBody: Node[]; pos: Position };

type Token =
  | { type: 'text'; value: string }
  | { type: 'interp'; path: string; pos: Position }
  | { type: 'raw'; path: string; pos: Position }
  | { type: 'ifOpen'; condition: string; pos: Position }
  | { type: 'eachOpen'; collection: string; pos: Position }
  | { type: 'else'; pos: Position }
  | { type: 'ifClose'; pos: Position }
  | { type: 'eachClose'; pos: Position };

export class TemplateError extends Error {
  constructor(
    message: string,
    public line: number,
    public col: number,
  ) {
    super(`Line ${line}, col ${col}: ${message}`);
    this.name = 'TemplateError';
  }
}

function getLineCol(template: string, offset: number): Position {
  let line = 1;
  let col = 1;
  for (let i = 0; i < offset && i < template.length; i++) {
    if (template[i] === '\n') {
      line++;
      col = 1;
    } else {
      col++;
    }
  }
  return { line, col };
}

function tokenize(template: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let textStart = 0;

  while (i < template.length) {
    if (template[i] === '{' && template[i + 1] === '{') {
      if (i > textStart) {
        tokens.push({ type: 'text', value: template.slice(textStart, i) });
      }

      const pos = getLineCol(template, i);
      const isRaw = template[i + 2] === '{';

      if (isRaw) {
        i += 3;
        const contentStart = i;
        const end = template.indexOf('}}}', contentStart);
        if (end === -1) {
          throw new TemplateError('Unclosed triple-mustache tag', pos.line, pos.col);
        }
        const path = template.slice(contentStart, end).trim();
        tokens.push({ type: 'raw', path, pos });
        i = end + 3;
      } else {
        i += 2;
        if (template[i] === '!') {
          const end = template.indexOf('}}', i);
          if (end === -1) {
            throw new TemplateError('Unclosed comment tag', pos.line, pos.col);
          }
          i = end + 2;
        } else {
          const contentStart = i;
          const end = template.indexOf('}}', contentStart);
          if (end === -1) {
            throw new TemplateError('Unclosed tag', pos.line, pos.col);
          }
          const content = template.slice(contentStart, end).trim();

          if (content.startsWith('#')) {
            if (content.startsWith('#if ')) {
              const condition = content.slice(4).trim();
              if (!condition) {
                throw new TemplateError('{{#if}} requires a condition path', pos.line, pos.col);
              }
              tokens.push({ type: 'ifOpen', condition, pos });
            } else if (content.startsWith('#each ')) {
              const collection = content.slice(6).trim();
              if (!collection) {
                throw new TemplateError('{{#each}} requires a collection path', pos.line, pos.col);
              }
              tokens.push({ type: 'eachOpen', collection, pos });
            } else if (content === '#if') {
              throw new TemplateError('{{#if}} requires a condition path', pos.line, pos.col);
            } else if (content === '#each') {
              throw new TemplateError('{{#each}} requires a collection path', pos.line, pos.col);
            } else {
              throw new TemplateError(`Unknown block: {{${content}}}`, pos.line, pos.col);
            }
          } else if (content.startsWith('/')) {
            if (content === '/if') {
              tokens.push({ type: 'ifClose', pos });
            } else if (content === '/each') {
              tokens.push({ type: 'eachClose', pos });
            } else {
              throw new TemplateError(`Unknown closing tag: {{${content}}}`, pos.line, pos.col);
            }
          } else if (content === 'else') {
            tokens.push({ type: 'else', pos });
          } else {
            tokens.push({ type: 'interp', path: content, pos });
          }
          i = end + 2;
        }
      }
      textStart = i;
    } else {
      i++;
    }
  }

  if (textStart < template.length) {
    tokens.push({ type: 'text', value: template.slice(textStart) });
  }

  return tokens;
}

function parse(tokens: Token[]): Node[] {
  let idx = 0;

  function parseNodes(stopAt: Set<string>): Node[] {
    const nodes: Node[] = [];
    while (idx < tokens.length) {
      const token = tokens[idx];
      switch (token.type) {
        case 'text':
          nodes.push({ type: 'text', value: token.value });
          idx++;
          break;
        case 'interp':
          nodes.push({ type: 'interp', path: token.path, pos: token.pos });
          idx++;
          break;
        case 'raw':
          nodes.push({ type: 'raw', path: token.path, pos: token.pos });
          idx++;
          break;
        case 'ifOpen': {
          idx++;
          const body = parseNodes(new Set(['else', 'ifClose']));
          let elseBody: Node[] = [];
          if (idx < tokens.length && tokens[idx].type === 'else') {
            idx++;
            elseBody = parseNodes(new Set(['ifClose']));
          }
          if (idx >= tokens.length || tokens[idx].type !== 'ifClose') {
            throw new TemplateError('Unclosed {{#if}} block', token.pos.line, token.pos.col);
          }
          idx++;
          nodes.push({ type: 'if', condition: token.condition, body, elseBody, pos: token.pos });
          break;
        }
        case 'eachOpen': {
          idx++;
          const body = parseNodes(new Set(['else', 'eachClose']));
          let elseBody: Node[] = [];
          if (idx < tokens.length && tokens[idx].type === 'else') {
            idx++;
            elseBody = parseNodes(new Set(['eachClose']));
          }
          if (idx >= tokens.length || tokens[idx].type !== 'eachClose') {
            throw new TemplateError('Unclosed {{#each}} block', token.pos.line, token.pos.col);
          }
          idx++;
          nodes.push({ type: 'each', collection: token.collection, body, elseBody, pos: token.pos });
          break;
        }
        case 'else':
          if (stopAt.has('else')) {
            return nodes;
          }
          throw new TemplateError('Unexpected {{else}}', token.pos.line, token.pos.col);
        case 'ifClose':
          if (stopAt.has('ifClose')) {
            return nodes;
          }
          throw new TemplateError('Unexpected {{/if}}', token.pos.line, token.pos.col);
        case 'eachClose':
          if (stopAt.has('eachClose')) {
            return nodes;
          }
          throw new TemplateError('Unexpected {{/each}}', token.pos.line, token.pos.col);
      }
    }
    return nodes;
  }

  return parseNodes(new Set());
}

class RenderContext {
  constructor(
    public root: unknown,
    public currentThis: unknown = undefined,
    public currentIndex: number | undefined = undefined,
  ) {}

  child(item: unknown, index: number): RenderContext {
    return new RenderContext(this.root, item, index);
  }
}

function resolvePropertyPath(obj: unknown, path: string): unknown {
  if (obj == null) {
    return undefined;
  }
  const parts = path.split('.');
  let current: unknown = obj;
  for (const part of parts) {
    if (current == null) {
      return undefined;
    }
    if (typeof current !== 'object') {
      return undefined;
    }
    current = (current as Record<string, unknown>)[part];
  }
  return current;
}

function resolvePath(path: string, ctx: RenderContext): unknown {
  if (path === 'this') {
    return ctx.currentThis;
  }
  if (path === '@index') {
    return ctx.currentIndex;
  }
  if (path.startsWith('this.')) {
    return resolvePropertyPath(ctx.currentThis, path.slice(5));
  }
  return resolvePropertyPath(ctx.root, path);
}

function isTruthy(value: unknown): boolean {
  if (value === null || value === undefined || value === false || value === 0 || value === '') {
    return false;
  }
  if (Array.isArray(value) && value.length === 0) {
    return false;
  }
  return true;
}

function renderScalar(value: unknown, pos: Position): string {
  if (value === null || value === undefined) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'number') {
    return String(value);
  }
  if (typeof value === 'boolean') {
    return String(value);
  }
  throw new TemplateError(`Cannot render ${typeof value} as text`, pos.line, pos.col);
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

function renderNodes(nodes: Node[], ctx: RenderContext): string {
  let result = '';
  for (const node of nodes) {
    switch (node.type) {
      case 'text':
        result += node.value;
        break;
      case 'interp': {
        const value = resolvePath(node.path, ctx);
        result += escapeHtml(renderScalar(value, node.pos));
        break;
      }
      case 'raw': {
        const value = resolvePath(node.path, ctx);
        result += renderScalar(value, node.pos);
        break;
      }
      case 'if': {
        const condValue = resolvePath(node.condition, ctx);
        if (isTruthy(condValue)) {
          result += renderNodes(node.body, ctx);
        } else {
          result += renderNodes(node.elseBody, ctx);
        }
        break;
      }
      case 'each': {
        const collection = resolvePath(node.collection, ctx);
        if (!isTruthy(collection)) {
          result += renderNodes(node.elseBody, ctx);
        } else if (Array.isArray(collection)) {
          for (let i = 0; i < collection.length; i++) {
            result += renderNodes(node.body, ctx.child(collection[i], i));
          }
        } else {
          throw new TemplateError(
            `{{#each}} requires an array, got ${typeof collection}`,
            node.pos.line,
            node.pos.col,
          );
        }
        break;
      }
    }
  }
  return result;
}

export function render(template: string, data: unknown): string {
  const tokens = tokenize(template);
  const ast = parse(tokens);
  const ctx = new RenderContext(data);
  return renderNodes(ast, ctx);
